SELECT a.FINANCIER_ID, o.ORG_NAME_AR FINANCIER_NAME_AR, o.ORG_TYPE_CODE, a.PROGRAM_VERSION_ID, pv.PROGRAM_CODE, a.STATUS_CODE, st.NAME_AR STATUS_NAME_AR, COUNT(*) APPLICATION_COUNT, SUM(NVL(a.REQUESTED_FINANCE_AMOUNT,0)) REQUESTED_FINANCE_TOTAL, SUM(NVL(a.APPROVED_FINANCE_AMOUNT,0)) APPROVED_FINANCE_TOTAL, SUM(NVL(a.TOTAL_SUBSIDY_AMOUNT,0)) SUBSIDY_TOTAL FROM MFF_APPLICATIONS a JOIN MFF_ORGANIZATIONS o ON o.ORG_ID = a.FINANCIER_ID JOIN MFF_PROGRAM_VERSIONS pv ON pv.PROGRAM_VERSION_ID = a.PROGRAM_VERSION_ID JOIN REF_MFF_APPLICATION_STATUS st ON st.CODE = a.STATUS_CODE GROUP BY a.FINANCIER_ID,o.ORG_NAME_AR,o.ORG_TYPE_CODE, a.PROGRAM_VERSION_ID,pv.PROGRAM_CODE,a.STATUS_CODE,st.NAME_AR;
